// - Line 195: ogs_assert(xact) - transaction pool
// - Line 207: ogs_assert(xact->tm_response) - timer pool
// - Line 214: ogs_assert(xact->tm_holding) - timer pool
// - Line 219: ogs_assert(xact->tm_peer) - timer pool

